function mix(a,b){return Object.assign({},a,b);}
function pad(n){return String(n).padStart(2,'0');}
function dayOf(ts){const d=new Date(ts);return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
function hhmm(ts){const d=new Date(ts);return pad(d.getHours())+':'+pad(d.getMinutes());}
function fmt(ms){const t=Math.max(0,Math.ceil(ms/1000));return pad(Math.floor(t/60))+':'+pad(t%60);}

function norm(s){
  s=s||{};
  const st=s.settings||{};
  const f=Number(st.focusMin),b=Number(st.breakMin);
  return {
    settings:{focusMin:f>0?f:25,breakMin:b>0?b:5},
    history:Array.isArray(s.history)?s.history:[],
    session:s.session&&typeof s.session==='object'?s.session:null
  };
}
function base(s){return mix(s||{},norm(s));}

function initialize(s){
  return base(s);
}

/* 把已到点的阶段结算掉：专注到点记一轮并自动进入休息，休息到点回到空闲。
   用结束时刻而不是当前时刻计算，所以关掉卡片再打开也能补上。 */
function settle(s,now){
  let ses=s.session,hist=s.history,changed=false,guard=0;
  while(ses&&ses.status==='running'&&ses.endsAt!=null&&now>=ses.endsAt&&guard<4){
    guard++;changed=true;
    if(ses.phase==='focus'){
      const at=ses.endsAt,sid=ses.id;
      if(!hist.some(h=>h.id===sid)){
        hist=hist.concat([{id:sid,day:dayOf(at),task:ses.task,minutes:Math.round(ses.total/60000),endedAt:at}]);
      }
      const total=s.settings.breakMin*60000;
      ses={id:sid+'b',phase:'break',task:ses.task,status:'running',total:total,endsAt:at+total,remainMs:total};
    }else{
      ses=null;
    }
  }
  if(!changed)return s;
  return mix(s,{session:ses,history:hist});
}

function remainOf(ses,now){
  if(!ses)return 0;
  return ses.status==='running'?Math.max(0,ses.endsAt-now):Math.max(0,ses.remainMs);
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,editor}=ctx;
  const S=norm(state);
  const ses=S.session;
  const today=day();
  let timeEl=null,ringEl=null;

  const keep=patch=>Object.assign({},ui,patch);
  function run(fn){
    ui.err='';
    fn().catch(()=>{ui.err='保存失败，请重试';redraw();});
  }

  function startRound(){
    const task=(ui.task||'').trim().slice(0,40);
    if(!task){ui.err='先写下这一轮要做什么';redraw();return;}
    run(()=>commit(s=>{
      const now=Date.now();
      s=settle(base(s),now);
      if(s.session)return s;
      const total=s.settings.focusMin*60000;
      return mix(s,{session:{id:uid(),phase:'focus',task:task,status:'running',total:total,endsAt:now+total,remainMs:total}});
    },keep({task:'',err:'',confirmAt:0})));
  }
  function pause(){
    run(()=>update(s=>{
      const now=Date.now();
      s=settle(base(s),now);
      const x=s.session;
      if(!x||x.status!=='running')return s;
      return mix(s,{session:mix(x,{status:'paused',remainMs:Math.max(0,x.endsAt-now),endsAt:null})});
    }));
  }
  function resume(){
    run(()=>update(s=>{
      const now=Date.now();
      s=settle(base(s),now);
      const x=s.session;
      if(!x||x.status!=='paused')return s;
      return mix(s,{session:mix(x,{status:'running',endsAt:now+x.remainMs})});
    }));
  }
  function abandon(){
    if(!ui.confirmAt){ui.confirmAt=Date.now();redraw();return;}
    ui.confirmAt=0;
    run(()=>update(s=>{
      s=settle(base(s),Date.now());
      return s.session&&s.session.phase==='focus'?mix(s,{session:null}):s;
    }));
  }
  function skipBreak(){
    run(()=>update(s=>{
      s=settle(base(s),Date.now());
      return s.session&&s.session.phase==='break'?mix(s,{session:null}):s;
    }));
  }

  function openDur(){
    ui.editDur=true;
    ui.draft={focus:String(S.settings.focusMin),rest:String(S.settings.breakMin)};
    ui.err='';ui.confirmAt=0;
    redraw();
  }
  function closeDur(){ui.editDur=false;ui.draft=null;redraw();}
  function saveDur(v){
    const f=Number(v.focus),b=Number(v.rest);
    if(!Number.isInteger(f)||f<1||f>180)return '专注时长请填 1–180 的整数分钟';
    if(!Number.isInteger(b)||b<1||b>60)return '休息时长请填 1–60 的整数分钟';
    const cur=S.session;
    if(cur){
      const nm=(cur.phase==='focus'?f:b)*60000;
      const elapsed=cur.total-remainOf(cur,Date.now());
      if(nm<=elapsed)return '本轮已进行 '+Math.ceil(elapsed/60000)+' 分钟，新时长需要更长';
    }
    return commit(s=>{
      const now=Date.now();
      s=settle(base(s),now);
      const settings={focusMin:f,breakMin:b};
      let x=s.session;
      if(x){
        const nm=(x.phase==='focus'?f:b)*60000;
        const elapsed=x.total-remainOf(x,now);
        const nrem=Math.max(nm-elapsed,1000);
        x=mix(x,{total:elapsed+nrem});
        x=x.status==='running'?mix(x,{endsAt:now+nrem,remainMs:nrem}):mix(x,{remainMs:nrem});
      }
      return mix(s,{settings:settings,session:x});
    },keep({editDur:false,draft:null,err:''}));
  }

  function settleNow(){
    if(ui.settling||(ui.retryAt&&Date.now()<ui.retryAt))return;
    ui.settling=true;
    update(s=>settle(base(s),Date.now())).then(
      ()=>{ui.settling=false;},
      ()=>{ui.settling=false;ui.retryAt=Date.now()+4000;}
    );
  }


  function paint(rem){
    if(!timeEl||!ses)return;
    timeEl.textContent=fmt(rem);
    const p=ses.total>0?Math.max(0,Math.min(100,rem/ses.total*100)):0;
    ringEl.style.setProperty('--p',String(p));
  }
  function tick(){
    if(day()!==today){redraw();return;}
    if(ui.confirmAt&&Date.now()-ui.confirmAt>4000){ui.confirmAt=0;redraw();return;}
    if(!ses||ses.status!=='running')return;
    const rem=ses.endsAt-Date.now();
    if(rem<=0){settleNow();return;}
    paint(rem);
  }

  function btn(cls,label,fn){
    return el('button',{type:'button',class:'btn '+cls,onclick:fn},label);
  }

  function buildRing(pre){
    const paused=ses&&ses.status==='paused';
    const phase=ses?ses.phase:'focus';
    const rem=ses?remainOf(ses,Date.now()):S.settings.focusMin*60000;
    timeEl=el('span',{class:'t'},fmt(rem));
    ringEl=el('div',{class:'ring '+phase+(paused?' paused':'')+(pre?' pre':'')},
      el('div',{class:'ringin'},timeEl,
        el('span',{class:'sub'},pre?'专注时长':(phase==='focus'?'专注剩余':'休息剩余'))));
    paint(rem);
    if(pre)ringEl.style.setProperty('--p','100');
    return ringEl;
  }

  function buildActive(){
    const paused=ses.status==='paused';
    const isFocus=ses.phase==='focus';
    const taskText=isFocus?ses.task:'休息一下，上一轮：'+ses.task;
    const ctrls=el('div',{class:'ctrls'},
      btn('primary',paused?'继续':'暂停',paused?resume:pause),
      btn('',  '改时长',openDur),
      isFocus?btn('ghost'+(ui.confirmAt?' warn':''),ui.confirmAt?'确认放弃':'放弃',abandon)
             :btn('ghost','跳过休息',skipBreak));
    return el('div',{class:'stage'},
      buildRing(false),
      el('div',{class:'info'},el('div',{class:'task',title:ses.task},taskText),ctrls));
  }

  function buildIdle(){
    const lbl=ui.err
      ?el('label',{class:'lbl err'},'⚠ '+ui.err)
      :el('label',{class:'lbl'},'这一轮要做什么？');
    const input=el('input',{class:'inp',type:'text',placeholder:'例如：写周报',value:ui.task||'',maxLength:40,
      'aria-label':'这一轮要做什么',
      oninput:e=>{ui.task=e.target.value;},
      onkeydown:e=>{if(e.key==='Enter'&&!e.isComposing&&e.keyCode!==229){e.preventDefault();startRound();}}});
    const seen={},recent=[];
    S.history.slice().sort((a,b)=>b.endedAt-a.endedAt).forEach(h=>{
      if(!seen[h.task]&&recent.length<6){seen[h.task]=1;recent.push(h.task);}
    });
    const chips=recent.length?el('div',{class:'chips'},...recent.map(t=>
      el('button',{type:'button',class:'chipb',title:t,onclick:()=>{ui.task=t;ui.err='';redraw();}},t))):null;
    const info=el('div',{class:'info'},lbl,input,
      btn('primary start','开始专注 '+S.settings.focusMin+' 分钟',startRound),
      el('button',{type:'button',class:'durbtn',onclick:openDur},
        '专注 '+S.settings.focusMin+' · 休息 '+S.settings.breakMin+' 分  ✎ 改时长'));
    if(chips)info.appendChild(chips);
    return el('div',{class:'stage idle'},buildRing(true),info);
  }

  function buildToday(list){
    const items=list.length
      ?list.map(h=>el('div',{class:'rd'},
          el('span',{class:'rt'},h.task),
          el('span',{class:'rm'},h.minutes+' 分钟 · '+hhmm(h.endedAt)+' 完成')))
      :[el('div',{class:'empty'},'今天还没有完成的轮次，专注结束后会记在这里。')];
    return el('div',{class:'today'},
      el('div',{class:'th'},el('span',{class:'tt'},'今天完成'),
        el('span',{class:'big'},el('b',{},String(list.length)),' 轮')),
      el('div',{class:'list'},...items));
  }

  function render(){
    while(root.firstChild)root.removeChild(root.firstChild);
    if(ui.editDur){
      root.appendChild(editor({title:'改时长',draft:ui.draft,
        fields:[
          {key:'focus',label:'专注（分钟）',type:'number',required:true,min:1,max:180,step:1},
          {key:'rest',label:'休息（分钟）',type:'number',required:true,min:1,max:60,step:1}
        ],onSave:saveDur,onBack:closeDur,submitLabel:'保存'}));
      return;
    }
    const todays=S.history.filter(h=>h.day===today).sort((a,b)=>b.endedAt-a.endedAt);
    const phaseText=!ses?'准备开始':(ses.phase==='focus'?'专注中':'休息中')+(ses.status==='paused'?' · 已暂停':'');
    const hd=el('div',{class:'hd'},
      el('span',{class:'chip '+(ses?ses.phase:'idle')},phaseText),
      el('span',{class:'mini'},'今天 '+todays.length+' 轮'));
    const main=el('div',{class:'main'},hd);
    if(ses&&ui.err)main.appendChild(el('div',{class:'err'},'⚠ '+ui.err));
    main.appendChild(ses?buildActive():buildIdle());
    root.appendChild(main);
    root.appendChild(buildToday(todays));
  }

  render();
  const first=setTimeout(tick,0);
  const timer=setInterval(tick,500);
  return ()=>{clearTimeout(first);clearInterval(timer);};
}

